def find_sp(inp):
    H,W=len(inp),len(inp[0])
    # prefer vertical, reject boundary-only; else horizontal, reject trailing row
    for c in range(W-1 if False else W):
        cc={inp[r][c] for r in range(H)}
        if len(cc)==1 and c<W: pass  # check below
    # vertical: any full uniform col except when it's the only column? allow col W-1 if W>1
    cand=[]
    for c in range(W):
        if len({inp[r][c] for r in range(H)})==1: cand.append(('v',c))
    for r in range(H):
        if len({inp[r][c] for c in range(W)})==1: cand.append(('h',r))
    # heuristic: choose first candidate where regions are non-empty-ish
    out=None
    for kind,v in cand:
        if kind=='v':
            Lh,Rh=len(inp),W-v-1
        else:
            Lh,Lw,vr=v,r
            Rh=H-vr-1 if kind=='h' else None
